// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    function testFuzz_property(address from, uint256 v, address[] memory _tos) public {
        vm.assume(_tos.length > 0);

        ReverterBySelector reverter = new ReverterBySelector();

        bool ok;
        try c.transfer(from, address(reverter), _tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

contract ReverterBySelector {
    fallback() external payable {
        bytes4 sig;
        assembly { sig := calldataload(0) }
        bytes4 bad = bytes4(keccak256("transfer(address,address,uint256)"));
        if (sig == bad) {
            revert("bad selector");
        }
    }
}
